// haze-ui registry block — generated by scripts/generate-registry.mjs
// from src/views/Blocks/blocks/FilterListBlock.tsx.
//
// Unlike the component items (thin re-export wrappers over the haze-ui npm
// package), a block is VENDORED source: a full page you own and edit.
// The component imports are rewritten from the docs site's '@/lib' alias
// to the published 'haze-ui' package and every stylesheet of the page's
// component closure is imported below, so the file is self-contained.
// npm dependencies beyond haze-ui: react-use-control.
//
// Theming (once per app): apply the token classes to a root element, e.g.
//   import { lightTheme, spacing, typography } from 'haze-ui';
//   <div className={`${lightTheme} ${spacing} ${typography}`}>…</div>
// (darkTheme is a drop-in swap).

import 'haze-ui/css/tokens.css';
import 'haze-ui/css/avatar.css';
import 'haze-ui/css/badge.css';
import 'haze-ui/css/button.css';
import 'haze-ui/css/card.css';
import 'haze-ui/css/checkbox.css';
import 'haze-ui/css/chip.css';
import 'haze-ui/css/empty.css';
import 'haze-ui/css/input.css';
import 'haze-ui/css/pagination.css';
import 'haze-ui/css/rating.css';
import 'haze-ui/css/select.css';
import 'haze-ui/css/spinner.css';
import 'haze-ui/css/virtual-list.css';

import type { ReactNode } from 'react';

import { useMemo } from 'react';
import { useControl } from 'react-use-control';

import {
  Avatar,
  Badge,
  Button,
  Card,
  Checkbox,
  Chip,
  Empty,
  Input,
  Option,
  Pagination,
  Rating,
  Select,
} from 'haze-ui';

/*
 * Filter list block: a catalog page with a filter rail. The rail (search
 * Input, category Checkboxes, region Select, sort Select) and the result
 * list never share components with the Crud/DataTable blocks — the list
 * itself is a stack of Cards, so this reads as a browsing page, not a
 * table page. Every filter is a Control (query / categories / region /
 * sort / page), active facets render as closable Chips, and an Empty
 * state plus Pagination close the loop.
 */

type CatalogItem = {
  id: string;
  name: string;
  description: string;
  category: 'automation' | 'data' | 'design' | 'docs';
  region: 'eu-central' | 'us-east' | 'ap-northeast';
  rating: number;
  installs: number;
  status: 'ready' | 'beta';
  updated: string;
};

const CATEGORY_LABELS: Record<CatalogItem['category'], string> = {
  automation: 'Automation',
  data: 'Data',
  design: 'Design',
  docs: 'Docs',
};

const CATALOG: CatalogItem[] = [
  { id: 'pipeline-watch', name: 'Pipeline Watch', description: 'Streaming health board for ingest pipelines, with SLO burn alerts.', category: 'data', region: 'eu-central', rating: 5, installs: 12840, status: 'ready', updated: '2 days ago' },
  { id: 'release-notes', name: 'Release Notes Bot', description: 'Turns merged PR labels into a drafted changelog every Friday.', category: 'automation', region: 'us-east', rating: 4, installs: 9310, status: 'ready', updated: '1 week ago' },
  { id: 'token-studio', name: 'Token Studio Sync', description: 'Two-way sync between the design token pipeline and the codebase.', category: 'design', region: 'eu-central', rating: 5, installs: 7725, status: 'ready', updated: '3 days ago' },
  { id: 'runbook-search', name: 'Runbook Search', description: 'Full-text search across on-call runbooks with incident tags.', category: 'docs', region: 'us-east', rating: 4, installs: 5410, status: 'ready', updated: '2 weeks ago' },
  { id: 'fleet-mapper', name: 'Fleet Mapper', description: 'Maps device fleets onto regions and utilization heat bands.', category: 'data', region: 'ap-northeast', rating: 4, installs: 4980, status: 'beta', updated: '5 days ago' },
  { id: 'handoff-kit', name: 'Handoff Kit', description: 'Figma frame to component scaffold, with a11y annotations intact.', category: 'design', region: 'ap-northeast', rating: 5, installs: 4102, status: 'ready', updated: '4 days ago' },
  { id: 'triage-rules', name: 'Triage Rules', description: 'Routes incoming issues to owners with a small rules DSL.', category: 'automation', region: 'eu-central', rating: 3, installs: 3611, status: 'ready', updated: '3 weeks ago' },
  { id: 'schema-docs', name: 'Schema Docs', description: 'Generates readable docs from protobuf and SQL schemas.', category: 'docs', region: 'eu-central', rating: 4, installs: 2870, status: 'beta', updated: '1 week ago' },
  { id: 'cohort-lens', name: 'Cohort Lens', description: 'Retention cohorts over the warehouse, no notebook required.', category: 'data', region: 'us-east', rating: 5, installs: 2614, status: 'ready', updated: '6 days ago' },
  { id: 'brand-lint', name: 'Brand Lint', description: 'CI check that new UI stays inside the brand token scales.', category: 'design', region: 'us-east', rating: 3, installs: 1980, status: 'ready', updated: '2 weeks ago' },
  { id: 'oncall-brief', name: 'Oncall Brief', description: 'Morning digest of what changed while the on-call slept.', category: 'automation', region: 'ap-northeast', rating: 4, installs: 1502, status: 'beta', updated: '3 days ago' },
  { id: 'policy-wiki', name: 'Policy Wiki', description: 'Versioned policy pages with review expirations and owners.', category: 'docs', region: 'ap-northeast', rating: 3, installs: 940, status: 'ready', updated: '1 month ago' },
];

const PAGE_SIZE = 5;

const SORTERS: Record<string, (a: CatalogItem, b: CatalogItem) => number> = {
  popular: (a, b) => b.installs - a.installs,
  rating: (a, b) => b.rating - a.rating || b.installs - a.installs,
  name: (a, b) => a.name.localeCompare(b.name),
};

function FilterSection({ title, children }: { title: string; children: ReactNode }) {
  return (
    <div
      data-slot='filter-section'
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--haze-space-2)',
        paddingTop: 'var(--haze-space-3)',
        borderTop: '1px solid var(--haze-color-border)',
      }}
    >
      <span
        style={{
          fontSize: 'var(--haze-text-xs)',
          fontWeight: 'var(--haze-weight-semibold)',
          letterSpacing: '0.04em',
          textTransform: 'uppercase',
          color: 'var(--haze-color-text-muted)',
        }}
      >
        {title}
      </span>
      {children}
    </div>
  );
}

function CatalogCard({ item }: { item: CatalogItem }) {
  return (
    <Card data-slot='catalog-card' variant='outlined'>
      <div
        style={{
          display: 'flex',
          alignItems: 'flex-start',
          gap: 'var(--haze-space-3)',
        }}
      >
        <Avatar fallback={item.name.slice(0, 2).toUpperCase()} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--haze-space-2)',
              flexWrap: 'wrap',
            }}
          >
            <span
              style={{
                fontSize: 'var(--haze-text-base)',
                fontWeight: 'var(--haze-weight-medium)',
              }}
            >
              {item.name}
            </span>
            <Badge color={item.status === 'ready' ? 'success' : 'info'}>
              {item.status === 'ready' ? 'Ready' : 'Beta'}
            </Badge>
            <span style={{ marginLeft: 'auto', whiteSpace: 'nowrap' }}>
              <Rating value={item.rating} allowHalf={false} />
            </span>
          </div>
          <p
            style={{
              margin: 'var(--haze-space-1) 0 0',
              fontSize: 'var(--haze-text-sm)',
              color: 'var(--haze-color-text-secondary)',
            }}
          >
            {item.description}
          </p>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: 'var(--haze-space-3)',
              marginTop: 'var(--haze-space-2)',
              fontSize: 'var(--haze-text-xs)',
              color: 'var(--haze-color-text-muted)',
            }}
          >
            <span>{CATEGORY_LABELS[item.category]}</span>
            <span>{item.installs.toLocaleString()} installs</span>
            <span>Updated {item.updated}</span>
          </div>
        </div>
      </div>
    </Card>
  );
}

export default function FilterListBlock() {
  // The whole filter state is user-facing — Controls, so a host app can
  // preset, observe or drive this page from a URL.
  const [query, setQuery, queryCtrl] = useControl(undefined, '');
  const [categories, setCategories] = useControl<string[]>(undefined, []);
  const [region, setRegion, regionCtrl] = useControl(undefined, 'all');
  const [sort, , sortCtrl] = useControl(undefined, 'popular');
  const [page, setPage, pageCtrl] = useControl(undefined, 1);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    const matched = CATALOG.filter((item) => {
      if (
        q &&
        !item.name.toLowerCase().includes(q) &&
        !item.description.toLowerCase().includes(q)
      ) {
        return false;
      }
      if (categories.length > 0 && !categories.includes(item.category)) {
        return false;
      }
      if (region !== 'all' && item.region !== region) return false;
      return true;
    });
    return [...matched].sort(SORTERS[sort] ?? SORTERS.popular);
  }, [query, categories, region, sort]);

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const pageItems = filtered.slice(
    (safePage - 1) * PAGE_SIZE,
    safePage * PAGE_SIZE
  );

  function toggleCategory(category: CatalogItem['category'], checked: boolean) {
    setCategories((prev) =>
      checked ? [...prev, category] : prev.filter((c) => c !== category)
    );
    setPage(1);
  }

  return (
    <div
      data-slot='filter-list-block'
      style={{
        display: 'flex',
        gap: 'var(--haze-space-5)',
        alignItems: 'flex-start',
        padding: 'var(--haze-space-5)',
        fontFamily: 'var(--haze-font-sans)',
        color: 'var(--haze-color-text)',
        background: 'var(--haze-color-bg)',
      }}
    >
      <Card data-slot='filter-rail' style={{ width: '260px', flexShrink: 0 }}>
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: 'var(--haze-space-3)',
          }}
        >
          <Input
            value={queryCtrl}
            size='sm'
            placeholder='Search the catalog…'
            aria-label='Search the catalog'
            onChange={(e) => {
              setQuery(e.currentTarget.value);
              setPage(1);
            }}
          />
          <FilterSection title='Category'>
            {(Object.keys(CATEGORY_LABELS) as CatalogItem['category'][]).map(
              (category) => (
                <Checkbox
                  key={category}
                  checked={categories.includes(category)}
                  label={CATEGORY_LABELS[category]}
                  onChange={(e) => toggleCategory(category, e.currentTarget.checked)}
                />
              )
            )}
          </FilterSection>
          <FilterSection title='Region'>
            <Select
              value={regionCtrl}
              size='sm'
              aria-label='Filter by region'
              onChange={(e) => {
                setRegion(e.currentTarget.value);
                setPage(1);
              }}
            >
              <Option value='all'>All regions</Option>
              <Option value='eu-central'>Frankfurt</Option>
              <Option value='us-east'>N. Virginia</Option>
              <Option value='ap-northeast'>Tokyo</Option>
            </Select>
          </FilterSection>
          <FilterSection title='Sort'>
            <Select value={sortCtrl} size='sm' aria-label='Sort order'>
              <Option value='popular'>Most installed</Option>
              <Option value='rating'>Highest rated</Option>
              <Option value='name'>Name A–Z</Option>
            </Select>
          </FilterSection>
          <Button
            size='sm'
            variant='outline'
            onClick={() => {
              setQuery('');
              setCategories([]);
              setRegion('all');
              setPage(1);
            }}
          >
            Reset filters
          </Button>
        </div>
      </Card>

      <div
        data-slot='filter-results'
        style={{ flex: 1, minWidth: 0, display: 'flex', flexDirection: 'column', gap: 'var(--haze-space-3)' }}
      >
        <div
          data-slot='results-header'
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--haze-space-2)',
            flexWrap: 'wrap',
            minHeight: '32px',
          }}
        >
          <span style={{ fontSize: 'var(--haze-text-sm)', color: 'var(--haze-color-text-secondary)' }}>
            {filtered.length} of {CATALOG.length} templates
          </span>
          {categories.map((category) => (
            <Chip
              key={category}
              variant='outline'
              onClose={() => toggleCategory(category as CatalogItem['category'], false)}
            >
              {CATEGORY_LABELS[category as CatalogItem['category']]}
            </Chip>
          ))}
          {region !== 'all' && (
            <Chip variant='outline' onClose={() => setRegion('all')}>
              Region: {region}
            </Chip>
          )}
        </div>

        {pageItems.length === 0 ? (
          <Empty description='No templates match these filters — reset them or try a shorter query.' />
        ) : (
          pageItems.map((item) => <CatalogCard key={item.id} item={item} />)
        )}

        <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
          <Pagination
            page={pageCtrl}
            total={filtered.length}
            pageSize={PAGE_SIZE}
            size='sm'
          />
        </div>
      </div>
    </div>
  );
}
